    public static class JanHus
    {
        private const string Source = "https://cs.wikiquote.org/wiki/Jan_Hus";

        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = Source, Text = "Bůh není rozumem obsažený, on všechny věci obsahá a obsáhl, a jeho žádná, neb on jest nesmírný.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Z neznalosti sebe povstává pýcha, z neznalosti Boha vzchází zoufalství.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Bůh jest mi svědkem, že co se mi falešně připisuje a skrze falešné svědky přičítá, toho jsem ani neučil ani nekázal, ale předním úmyslem mého kázání i všech jiných mých skutků bylo osvoboditi lidi od hříchů. V té pak pravdě evangelia, kterou jsem učil, psal a kázal, dnes vesele chci zemříti.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Láska jest dar Boží, jimž člověk jest Bohu vzácen.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Protož věz, že člověka zlého máš milovati, ale zloby jeho nemilovati.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Protož, věrný křesťane, hledaj pravdy, slyš pravdu, uč sě pravdě, miluj pravdu, prav pravdu, drž pravdu, braň pravdy až do smrti: nebť pravda tě vysvobodí od hřiecha, od ďábla, od smrti dušě a konečně od smrti věčné, jenž jest odlúčenie věčné od milosti Božie.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Nemohu-li já pravdy osvoboditi ve všem, aspoň nechci býti nepřítelem pravdy.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Kdo mluví pravdu, hlavu si rozbíjí.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Křesťan má být stálý ve víře a v rozjímání této trojí pravdy: té, která je obsažena v Písmu, té, kterou poznáváme smysly a té, jíž dosahujeme neomylným rozumem. Je lépe za tuto trojí pravdu vytrpět smrt než získat obročí pochlebováním.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Přítel Páleč, přítelkyně pravda: ale přednost je třeba dát pravdě.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Raději dávej se přemáhati mluvě pravdu, než bys chtěl vítězit lha, ježto lépe jest býti přemožen pravdu mluvě než vítěziti lha.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Vyznání úst bez víry není srdečné, ani víra bez vyznání není platná.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Protož diem to k svědomí, že bych znal cizozemce odkudkoli, v jeho ctnosti an viece boha miluje, a o dobré stojí než moj vlastní bratr, byl mi milejší než bratr.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Lépe jest dobře zemříti, nežli zle živu býti. Pro trest smrti nemá se hřešiti... Kdo smrti se bojí, ztrácí radosti života. Nade vším vítězí pravda. Vítězí, kdo jest usmrcován.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Jeden doktor mi řekl, že ať bych ve snaze podvoliti se koncilu učinil cokoli, všechno je mi dobré a dovolené, a dodal: „Kdyby koncil řekl, ‚Ty máš jenom jedno oko‘, ačkoli máš dvě, musil bys s koncilem vyznati, že tomu tak jest.\" Řekl jsem mu: „I kdyby mi to celý svět říkal, já, maje rozum, jehož nyní užívám, nemohl bych to říci bez odporu svědomí.\"", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Protož já vyznávám svú zlú žádost, že když jsem byl žáčkem, tehdy měl sem mysl, abych brzo byl knězem, abych tak měl dobré bydlo a rúcho a byl lidem vzácen.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Od začátku svého studia jsem si učinil zásadu, že kdekoli poznám mínění správnější, ihned upustím od svého méně správného a pokorně a radostně přijmu názor, odůvodněný lépe.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Nešťastným bohatstvím, v němž církev tone zjedovatělo, a otráveno je téměř všechno křesťanstvo. Psi se o kost hrýžou. Vezmi kost a přestanou.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Kazatel má vyprati své sítě, to jest řeč vyčistiti, jíž má lidi z moře tohoto světa Kristu loviti, tak aby kázal čisté ustanovení Boží, ne bajky, ani lži, ani neužitečné řeči, a ovšem ne tak, aby lidi sváděl nebo loupil.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Nemodlí-li se kdo v srdci, nadarmo pracuje jazykem a ničeho nedosáhne.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Nehodně se modlí všichni, kdo prosí, aby se jim povedl jejich hřích.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "(O Otčenáši) Přesahá tato modlitba jiné v užitku; neb všecko, což jest potřebné duši nebo tělu, to vše v sedmi kusích té modlitby jest zavříno. A divným obyčejem, že nic neprosí, než co každému jest potřebno, protož bezpečně můžeme ji podati Pánu Bohu.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Modlitba jest řečení neb činění, kterýmž mysl člověka v Boha neb k Bohu nábožně se pozdvihá.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Je totiž nezbytné, má-li vůbec nastat mír s bližním, aby byl napřed uzavřen mír člověka s Bohem a mír člověka se sebou samým.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Mír má tři různé stránky: mír člověka s Bohem, člověka se sebou samým a člověka s bližním. A celý tento mír má svůj základ v zachovávání Božích příkazů.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "/je sedm duchovních skutků milosrdenství/ - a ty sú: učiti hlúpého, raditi pochybujícímu, tresktati hřěšícieho, těšiti zarmúceného neb smutného, odpustiti vinu blížniemu, trpěti mile protivenstvie křivé, modliti sě i za nepřátely.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Zlo je trojího druhu: přítomné, minulé a budoucí.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Stálý pak je ten, koho úspěchy nesvedou a protivenství neodstraší.", Author = "Jan Hus" },
            new Quote { Id = Source, Text = "Neb i družina v boji více toho rytíře miluje, který se po ústupu vrátí a nepřítele silně tiskne neb tepe, než toho, který nikdy neustoupil, a také nikdy nic silně neučinil.", Author = "Jan Hus" },
        };
    }
